args<-commandArgs(trailingOnly=TRUE);if(length(args)<3)stop("Usage: script full.csv mri.csv out")
full_path<-args[1];mri_path<-args[2];out_dir<-args[3];dir.create(out_dir,recursive=T,showWarnings=F)
options(stringsAsFactors=F,warn=1);suppressPackageStartupMessages(library(survival));suppressPackageStartupMessages(library(splines))
save_csv<-function(x,n)write.csv(x,file.path(out_dir,n),row.names=F,na="",fileEncoding="UTF-8")
z<-function(x){x<-as.numeric(x);as.numeric((x-mean(x,na.rm=T))/sd(x,na.rm=T))}
eth4<-function(x){x<-tolower(trimws(as.character(x)));w<-x%in%c("british","irish","white","any other white background");a<-x%in%c("indian","pakistani","bangladeshi","chinese","asian or asian british","any other asian background");b<-x%in%c("caribbean","african","black or black british","any other black background");factor(ifelse(w,"White",ifelse(a,"Asian",ifelse(b,"Black","Other/unknown"))),levels=c("White","Asian","Black","Other/unknown"))}
vcov_hcw<-function(f){X<-model.matrix(f);u<-residuals(f);h<-pmin(hatvalues(f),.999999);w<-weights(f);if(is.null(w))w<-rep(1,nrow(X));B<-solve(crossprod(X,X*w));S<-X*(w*u/(1-h));V<-B%*%crossprod(S)%*%B;dimnames(V)<-list(colnames(X),colnames(X));V}
tlm<-function(f,t,m){b<-coef(f)[t];se<-sqrt(vcov_hcw(f)[t,t]);data.frame(outcome="BAG",model=m,term=t,beta=unname(b),se=unname(se),CI_low=unname(b-1.96*se),CI_high=unname(b+1.96*se),HR=NA_real_,p=unname(2*pnorm(-abs(b/se))),n=nobs(f),events=NA)}
tcx<-function(f,t,m){b<-coef(f)[t];se<-sqrt(vcov(f)[t,t]);data.frame(outcome="Incident_CKD",model=m,term=t,beta=unname(b),se=unname(se),HR=unname(exp(b)),CI_low=unname(exp(b-1.96*se)),CI_high=unname(exp(b+1.96*se)),p=unname(2*pnorm(-abs(b/se))),n=f$n,events=f$nevent)}
cat("Reading cohorts...\n");full<-read.csv(full_path,check.names=F,na.strings=c("","NA"));mri<-read.csv(mri_path,check.names=F,na.strings=c("","NA"))
full$bd<-as.Date(substr(full$baseline_date,1,10));full$t0<-as.Date(substr(full$time0_full,1,10));full$age_webq<-as.numeric(full$Age_at_recruitment)+as.numeric(full$t0-full$bd)/365.25;full$sex_factor<-relevel(factor(full$Sex),ref="Female");full$ethnicity4<-eth4(full$Ethnic_0);full$tdi<-as.numeric(full$TDI_at_recruitment);full$edu_z<-as.numeric(full$area_education_deprivation_z);full$edu_miss<-factor(ifelse(is.na(full$edu_z),"Missing","Observed"));full$edu_imp<-ifelse(is.na(full$edu_z),0,full$edu_z);full$center<-factor(full$baseline_center);full$energy_z<-z(full$energy_kcal_primary);full$rounds<-as.numeric(full$webq_n_dates);full$LE8_per10<-as.numeric(full$LE8)/10;full$egfr<-as.numeric(full$egfr_cys_do);full$loguacr<-log1p(as.numeric(full$uacr));full$nonhdl_per10<-as.numeric(full$le8_nonhdl)/10
mri$sex_factor<-relevel(factor(mri$Sex),ref="Female");mri$ethnicity4<-eth4(mri$Ethnic_0);mri$tdi<-as.numeric(mri$TDI_at_recruitment);mri$edu_z<-as.numeric(mri$area_education_deprivation_z);mri$edu_miss<-factor(ifelse(is.na(mri$edu_z),"Missing","Observed"));mri$edu_imp<-ifelse(is.na(mri$edu_z),0,mri$edu_z);mri$center<-factor(mri$v4);mri$energy_z<-z(mri$energy_kcal_pre_mri_mean);mri$gap_years<-as.numeric(mri$webq_mri_gap_days)/365.25;mri$v_scaling_z<-z(mri$v_scaling_t1_to_standard_2);mri$scanner_x_z<-z(mri$scanner_lateral_x_brain_2);mri$scanner_y_z<-z(mri$scanner_transverse_y_brain_2);mri$scanner_z_z<-z(mri$scanner_longitudinal_z_brain_2);mri$scanner_table_z<-z(mri$scanner_table_position_2);mri$t2flair_qc<-factor(mri$t2flair_run_freesurfer_2);mri$LE8_per10<-as.numeric(mri$LE8)/10
fcov<-"age_webq+sex_factor+ethnicity4+tdi+edu_imp+edu_miss+center+energy_z+rounds";bcov<-"age+sex_factor+ethnicity4+tdi+edu_imp+edu_miss+center+energy_z+gap_years+v_scaling_z+scanner_x_z+scanner_y_z+scanner_z_z+scanner_table_z+t2flair_qc"
cat("Running CKD covariate and landmark sensitivities...\n")
c0<-coxph(as.formula(paste("Surv(followup_years,kidney_event)~LE8_per10+",fcov)),data=full);c1<-coxph(as.formula(paste("Surv(followup_years,kidney_event)~LE8_per10+egfr+",fcov)),data=full);c2<-coxph(as.formula(paste("Surv(followup_years,kidney_event)~LE8_per10+egfr+loguacr+",fcov)),data=full);land<-full[full$followup_years>2,];cl<-coxph(as.formula(paste("Surv(rep(2,nrow(land)),followup_years,kidney_event)~LE8_per10+",fcov)),data=land)
cs<-rbind(tcx(c0,"LE8_per10","Primary"),tcx(c1,"LE8_per10","Plus_baseline_eGFR"),tcx(c2,"LE8_per10","Plus_eGFR_UACR_complete_case"),tcx(cl,"LE8_per10","Two_year_landmark"));save_csv(cs,"Table_P2_total_LE8_CKD_sensitivities.csv")
components<-c("le8_diet_primary","le8_pa","le8_nicotine","le8_sleep","le8_bmi","le8_nonhdl","le8_glucose","le8_bp");labs<-setNames(c("Diet","Physical_activity","Nicotine_exposure","Sleep","BMI","Non_HDL_cholesterol","Blood_glucose","Blood_pressure"),components);for(v in components)full[[paste0(v,"_per10")]]<-as.numeric(full[[v]])/10;terms<-paste0(components,"_per10")
sep<-vector("list",8);for(i in 1:8){t<-terms[i];f<-coxph(as.formula(paste("Surv(followup_years,kidney_event)~",t,"+egfr+",fcov)),data=full);sep[[i]]<-cbind(component=labs[components[i]],tcx(f,t,"Separate_plus_eGFR"))};fm<-coxph(as.formula(paste("Surv(followup_years,kidney_event)~",paste(terms,collapse="+"),"+egfr+",fcov)),data=full);mut<-vector("list",8);for(i in 1:8)mut[[i]]<-cbind(component=labs[components[i]],tcx(fm,terms[i],"Mutual_plus_eGFR"));cr<-rbind(do.call(rbind,sep),do.call(rbind,mut));cr$p_FDR<-ave(cr$p,cr$model,FUN=function(x)p.adjust(x,"BH"));save_csv(cr,"Table_P2_components_CKD_plus_eGFR.csv")
cat("Building MRI selection weights...\n")
full$in_mri<-as.integer(as.character(full$participant_id)%in%as.character(mri$participant_id));sel<-glm(in_mri~ns(age_webq,df=4)+sex_factor+ethnicity4+tdi+edu_imp+edu_miss+center+LE8_per10+egfr,data=full,family=binomial());full$psel<-predict(sel,newdata=full,type="response");pm<-mean(full$in_mri);wmap<-full[,c("participant_id","psel")];mri<-merge(mri,wmap,by="participant_id",all.x=T,sort=F);mri$sw<-pm/mri$psel;q<-quantile(mri$sw,c(.01,.99),na.rm=T);mri$sw_trim<-pmin(pmax(mri$sw,q[1]),q[2]);ess<-function(w)(sum(w,na.rm=T)^2/sum(w^2,na.rm=T));wd<-data.frame(metric=c("Full_source_n","MRI_matched_to_source","MRI_OOS_BAG_weighted_n","Selection_probability_mean","Weight_p01","Weight_median","Weight_p99","Effective_sample_size"),value=c(nrow(full),sum(!is.na(mri$psel)),sum(!is.na(mri$psel)&!is.na(mri$brain_age_gap_oos_candidate)),mean(mri$psel,na.rm=T),q[1],median(mri$sw,na.rm=T),q[2],ess(mri$sw_trim[!is.na(mri$brain_age_gap_oos_candidate)])));save_csv(wd,"Table_P2_MRI_selection_weight_diagnostics.csv")
bu<-lm(as.formula(paste("brain_age_gap_oos_candidate~LE8_per10+",bcov)),data=mri);bw<-lm(as.formula(paste("brain_age_gap_oos_candidate~LE8_per10+",bcov)),data=mri,weights=sw_trim);ipw<-rbind(tlm(bu,"LE8_per10","Unweighted_OOS_BAG"),tlm(bw,"LE8_per10","Selection_IPW_OOS_BAG"));save_csv(ipw,"Table_P2_MRI_selection_IPW_total_LE8.csv")
cat("Auditing IPW balance...\n")
wm<-function(x,w)sum(x*w,na.rm=T)/sum(w[!is.na(x)],na.rm=T);wv<-function(x,w){mu<-wm(x,w);sum(w*(x-mu)^2,na.rm=T)/sum(w[!is.na(x)],na.rm=T)}
full$male<-as.numeric(full$Sex=="Male");mri$male<-as.numeric(mri$Sex=="Male");full$white<-as.numeric(full$ethnicity4=="White");mri$white<-as.numeric(mri$ethnicity4=="White");mri$egfr<-as.numeric(mri$egfr_cys_do)
vars<-c("Age_at_recruitment","LE8_per10","tdi","egfr","male","white");bal<-vector("list",length(vars));for(i in seq_along(vars)){v<-vars[i];a<-as.numeric(full[[v]]);b<-as.numeric(mri[[v]]);w<-mri$sw_trim;ma<-mean(a,na.rm=T);va<-var(a,na.rm=T);mb<-mean(b,na.rm=T);vb<-var(b,na.rm=T);mw<-wm(b,w);vw<-wv(b,w);bal[[i]]<-data.frame(variable=v,source_mean=ma,MRI_unweighted_mean=mb,MRI_weighted_mean=mw,SMD_unweighted=(mb-ma)/sqrt((va+vb)/2),SMD_weighted=(mw-ma)/sqrt((va+vw)/2))};save_csv(do.call(rbind,bal),"Table_P2_MRI_selection_balance.csv")
